// Template: quote_sent/fr — rendu inline (versionné dans /n8n/email-templates)
const input = $('Execute Workflow Trigger').first().json;
const payload = input.payload || input;
const d = payload.data || {};
const c = d.client || {};
const org = d.org || d.organization || {};

const SUBJECT_TPL = "Devis {{number}} \u2014 \u00e0 votre attention";
const BODY_MJML = "<mjml><mj-body><mj-section><mj-column>\n      <mj-text>Bonjour {{client.name}},</mj-text>\n      <mj-text>Veuillez trouver ci-joint le devis <strong>{{number}}</strong>.</mj-text>\n      <mj-button href=\"{{portalUrl}}\">Acc\u00e9der au portail</mj-button>\n      <mj-text>{{org.name}}</mj-text>\n      <mj-text><a href=\"{{unsubscribeUrl}}\">Se d\u00e9sabonner</a></mj-text>\n    </mj-column></mj-section></mj-body></mjml>";

// Contexte de résolution des placeholders {{...}}
const ctx = {
  ...d,
  client: { name: c.name || '', email: c.email || '' },
  org: {
    name: org.name || '', logoUrl: org.logoUrl || '',
    brandColor: org.brandColor || '#111827',
    email: org.email || '', phone: org.phone || '',
  },
  portalUrl: d.portalUrl || '',
  unsubscribeUrl: d.unsubscribeUrl || '',
};

function lookup(path) {
  return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), ctx);
}
function resolve(tpl) {
  return tpl.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, p) => {
    const v = lookup(p);
    return v == null ? '' : String(v);
  });
}

// MJML -> HTML. mjml est optionnel dans l'image n8n : fallback si absent.
function compile(mjmlSource) {
  try {
    const mjml2html = require('mjml');
    const out = mjml2html(mjmlSource, { validationLevel: 'soft' });
    if (out && out.html) return out.html;
  } catch (e) {
    // mjml non installé -> dégradation contrôlée vers un HTML simple
  }
  const body = mjmlSource
    .replace(/<mj-button[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/mj-button>/g,
             '<p><a href="$1">$2</a></p>')
    .replace(/<mj-text[^>]*>([\s\S]*?)<\/mj-text>/g, '<p>$1</p>')
    .replace(/<\/?mj-(?:mjml|body|section|column|raw)[^>]*>/g, '')
    .replace(/<\/?mjml[^>]*>/g, '');
  return '<!doctype html><html><body>' + body + '</body></html>';
}

const to = [c.email].filter(Boolean);
if (!to.length) {
  throw new Error('Aucun destinataire résolu pour quote_sent (event ' + (payload.id || '?') + ')');
}

return [{ json: {
  eventId: payload.id || '',
  organizationId: payload.organizationId || '',
  to,
  subject: resolve(SUBJECT_TPL).trim(),
  html: compile(resolve(BODY_MJML)),
  pdfDownloadUrl: d.pdfUrl || d.pdfDownloadUrl || '',
  pdfFilename: (d.number ? String(d.number) : 'document') + '.pdf',
} }];

// Limite MVP5 §5.4 : au-delà de 10 Mo, on envoie le lien au lieu de la pièce jointe.
const MAX_BYTES = 10 * 1024 * 1024;
const rendered = $('Render Email').first().json;
const binary = $input.first().binary?.data;
if (!binary) {
  return [{ json: { ...rendered, attachments: [] } }];
}
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (buf.length > MAX_BYTES) {
  return [{ json: {
    ...rendered,
    html: rendered.html.replace('</body>',
      '<p><a href="' + rendered.pdfDownloadUrl + '">Télécharger le document (PDF)</a></p></body>'),
    attachments: [],
  } }];
}
return [{ json: {
  ...rendered,
  attachments: [{
    filename: rendered.pdfFilename,
    content: buf.toString('base64'),
    content_type: 'application/pdf',
  }],
} }];
